import { loadContent } from './content-loader.js';
import { createWiki, matchesQuery } from './wiki.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',path:'<path d="M5 5h14M5 12h14M5 19h14"/><circle cx="5" cy="5" r="2"/><circle cx="14" cy="12" r="2"/><circle cx="8" cy="19" r="2"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',box:'<path d="m12 2 10 5v10l-10 5-10-5V7l10-5Zm0 10 10-5M12 12 2 7m10 5v10M7 4.5l10 5"/>',book:'<path d="M12 5C8 2 4 3 2 4v16c3-2 7-1 10 1 3-2 7-3 10-1V4c-3-2-7-1-10 1Zm0 0v16"/>',note:'<path d="M4 3h16v18H4zM8 7h8M8 11h8M8 15h5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m4 12 5 5L20 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',play:'<path d="m8 4 13 8-13 8V4Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const KEY='fieldwork.progress.v1';
const initial=()=>({version:1,lessons:[],labs:[],projects:{},notes:{},code:{},quiz:{},lastLesson:'lesson-01',days:[],goal:4});
let state=initial();
try{const stored=JSON.parse(localStorage.getItem(KEY)||'{}');if(stored&&stored.version===1){for(const key of ['lessons','labs','days'])if(Array.isArray(stored[key]))state[key]=[...new Set(stored[key].filter(x=>typeof x==='string'))];for(const key of ['projects','notes','code','quiz'])if(stored[key]&&typeof stored[key]==='object'&&!Array.isArray(stored[key]))state[key]=Object.fromEntries(Object.entries(stored[key]).filter(([k,v])=>!['__proto__','constructor','prototype'].includes(k)&&(key==='projects'?typeof v==='boolean':key==='quiz'?Number.isInteger(v)&&v>=0&&v<=3:typeof v==='string')));if(typeof stored.lastLesson==='string')state.lastLesson=stored.lastLesson;}}catch{}
let wikiUI,data,route,worker,timer,pdfURL,filterStage=0,filterType='All',searchText='',labResult=null,hints=0;
const today=()=>new Date().toLocaleDateString('en-CA');
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Storage is unavailable or full. Export a backup to keep your work.');return false;}};
const activity=()=>{if(!state.days.includes(today()))state.days.push(today());save();};
const done=id=>state.lessons.includes(id);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const link=(to,text,cls='')=>`<a class="${cls}" href="#/${to}">${text}</a>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const pct=(n,total)=>Math.round(n/Math.max(total,1)*100);
const stageName=id=>data.stages.find(s=>s.id===id)?.title||`Stage ${id}`;
const navItems=[['dashboard','grid','Overview'],['path','path','Learning path'],['labs','code','Practice lab'],['projects','box','Build projects'],['wiki','book','JavaScript wiki'],['library','book','Library'],['notebook','note','My notebook']];
function brand(){return link('',`<span class="brand-mark">f<span>↗</span></span><span>FIELDWORK<small>THE JAVASCRIPT STUDIO</small></span>`,'brand');}
function shell(content,active='dashboard'){
 return `<div class="workspace"><aside class="sidebar">${brand()}<div class="sidebar-label">YOUR WORKSPACE</div><nav>${navItems.map(([to,ic,title])=>link(to,`${icon(ic)}<span>${title}</span>${to==='labs'?'<small>48</small>':''}`,active===to?'active':'')).join('')}</nav><div class="side-bottom"><div class="book-tile"><span class="tiny-label">YOUR FIELD GUIDE</span>${icon('book')}<strong>JavaScript:<br>The Definitive Guide</strong><small>David Flanagan · 7th edition</small><button class="text-button" data-action="book">Open your copy ${icon('arrow')}</button></div><div class="profile"><span class="avatar">Y</span><div>Your learning space<small>Saved on this device</small></div><span class="online-dot"></span></div></div></aside><div class="workspace-body"><header class="workspace-header"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('path')}</button><span class="breadcrumb">The studio <span>/</span> ${navItems.find(x=>x[0]===active)?.[2]||'Learning path'}</span><button class="search-trigger" data-action="search" aria-label="Search the studio">${icon('search')}<span>Find anything</span><kbd>⌘ K</kbd></button><a class="header-home" href="#/">Explore Fieldwork ↗</a></header><main id="main" class="main-content">${content}</main><footer class="workspace-footer"><span>Made for the work between “I get it” and “I built it.”</span><span>INDEPENDENT BOOK COMPANION · V1.0</span></footer></div></div>`;
}
function home(){
 const practiceCount=data.lessons.reduce((n,l)=>n+(l.practice?.length||0),0);
 return `<div class="landing"><header class="landing-nav">${brand()}<nav><a href="#curriculum">The curriculum</a><a href="#method">The method</a>${link('library','The library')}</nav>${link('dashboard',`Enter the studio ${icon('arrow')}`,'button dark small')}</header><main id="main"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> A FIELD GUIDE TO THINKING IN JAVASCRIPT</div><h1>Read the book.<br>Write the code.<br><em>Make it yours.</em></h1><p>Deep understanding comes from doing. Turn <i>JavaScript: The Definitive Guide</i> into a practice of building, breaking, and figuring things out.</p><div class="hero-actions">${link('dashboard',`Start your fieldwork ${icon('arrow')}`,'button orange')}<a class="text-link" href="#curriculum">Explore the learning path ↘</a></div><div class="hero-note"><span class="mini-stack">{ } &nbsp; → &nbsp; ✓</span> Self-paced. Hands-on. Yours to keep.</div></div><div class="hero-art" aria-label="Illustration of the JavaScript learning journey"><div class="art-grid"></div><div class="art-top"><span>FIELD NOTES / 001</span><span>JAVASCRIPT</span></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="js-monolith"><div class="monolith-top"></div><div class="monolith-side"></div><div class="monolith-face"><span>THE LANGUAGE<br>IS JUST THE START.</span><strong>JS<span>↗</span></strong></div></div><div class="floating-code"><div><i></i><i></i><i></i><span>your-next-idea.js</span></div><code><span>const</span> understanding =<br>&nbsp; knowledge.<b>map</b>(practice);<br><br><span>await</span> you.<b>build</b>(something);</code></div><div class="art-label">01 — THINK IT THROUGH<br>02 — MAKE IT WORK<br>03 — MAKE IT BETTER</div><div class="art-stamp">LESS THEORY<br>WITHOUT<br><b>PRACTICE.</b></div></div></section><div class="stats-strip"><div><strong>${data.lessons.length}</strong><span>guided lessons</span></div><div><strong>${data.labs.length}</strong><span>executable labs</span></div><div><strong>${practiceCount}</strong><span>practice prompts</span></div><div><strong>06</strong><span>portfolio projects</span></div><p>ONE BOOK.<br>A WHOLE LOT OF POSSIBILITIES.</p></div><section id="curriculum" class="landing-section"><div class="section-title"><div><span class="eyebrow">THE LEARNING PATH</span><h2>From first principles<br>to things that work.</h2></div><p>Six stages. One intentional progression.<br>Read a little. Practice a lot. Build something real.</p></div><div class="stage-grid">${data.stages.map((s,i)=>`<a class="stage-card stage-${s.id}" href="#/path/${s.id}"><div class="card-top"><span>0${s.id} / STAGE</span>${icon('arrow')}</div><div class="stage-symbol">${['{ }','[ ]','ƒ(x)','↔','&lt;/&gt;','⌘'][i]}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="card-meta">6 LESSONS <span>·</span> ${esc(s.chapters)}</div></a>`).join('')}</div></section><section id="method" class="method"><div><span class="eyebrow">BUILT FOR UNDERSTANDING</span><h2>The part the<br>book can’t do<br><em>for you.</em></h2><p>A reading list is a start. Fieldwork gives you the structure to turn each chapter into a skill you can actually use.</p>${link('labs','Try a coding lab '+icon('arrow'),'button orange')}</div><div class="method-steps">${[['01','Read with a question','Every lesson points to a book section, sets concrete objectives, and explains the tricky parts in original language.'],['02','Predict. Run. Investigate.','Write code in your browser, run real assertions, and work through progressive hints. Solutions are there when you need them.'],['03','Build your evidence','Put each stage to work in a portfolio project. Use milestones, acceptance criteria, and a review rubric to guide the finish.'],['04','Reflect and return','Keep field notes, revisit weak spots, and export your progress. Understanding gets stronger when you retrieve it.']].map(([n,t,p])=>`<div><span>${n}</span><section><h3>${t}</h3><p>${p}</p></section></div>`).join('')}</div></section><section class="landing-section library-preview"><span class="eyebrow">YOUR SECOND BRAIN, WELL STOCKED</span><h2>Go beyond the chapter.</h2><p>Original field notes. Authoritative documentation. Free books, courses, and carefully selected talks.</p><div class="resource-preview-grid">${data.articles.slice(0,3).map((a,i)=>link('article/'+a.id,`<span class="tiny-label">FIELD NOTE / 0${i+1}</span><h3>${esc(a.title)}</h3><span>${a.minutes} MIN READ ${icon('arrow')}</span>`,'article-preview')).join('')}</div>${link('library','Explore the whole library '+icon('arrow'),'text-link')}</section><section class="final-cta"><span class="eyebrow">THE NEXT CHAPTER STARTS WITH YOU</span><h2>You don’t need another bookmark.<br>You need a place to begin.</h2>${link('lesson/lesson-01','Open your first lesson '+icon('arrow'),'button dark')}</section></main><footer class="landing-footer">${brand()}<p>An independent companion to David Flanagan’s book.<br>Original training content. No affiliation with O’Reilly.</p>${link('notebook','Your data stays with you ↗')}</footer></div>`;
}
function progressBar(value){return `<div class="progress-track"><span style="width:${value}%"></span></div>`;}
function dashboard(){
 const next=data.lessons.find(l=>l.id===state.lastLesson&&!done(l.id))||data.lessons.find(l=>!done(l.id))||data.lessons[0];
 const count=state.lessons.length;const percent=pct(count,data.lessons.length);
 return shell(`<div class="page-intro"><div><span class="eyebrow">YOUR PERSONAL LEARNING STUDIO</span><h1>${count?'Keep the momentum.':'Great things start with curiosity.'}</h1><p>${count?'Make a little room for your next breakthrough.':'A little reading. A lot of building. Let’s make JavaScript click.'}</p></div><span class="date-label">${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span></div><div class="dashboard-hero"><div><span class="tiny-label">${count?'CONTINUE YOUR JOURNEY':'YOUR FIRST FIELD ASSIGNMENT'}</span><h2>${esc(next.title)}</h2><p>${esc(next.subtitle)}</p><div class="inline-meta"><span>${esc(next.chapter)}</span><span>${icon('clock')} ${next.minutes} min</span></div>${link('lesson/'+next.id,`${count?'Continue learning':'Start lesson 01'} ${icon('arrow')}`,'button orange')}</div><div class="progress-orbit" style="--progress:${percent*3.6}deg"><div><strong>${percent}<span>%</span></strong><small>OF THE PATH EXPLORED</small></div></div></div><div class="metric-grid"><div><span>Lessons completed ${icon('book')}</span><strong>${count}<small> / ${data.lessons.length}</small></strong>${progressBar(percent)}</div><div><span>Labs solved ${icon('code')}</span><strong>${state.labs.length}<small> / ${data.labs.length}</small></strong>${progressBar(pct(state.labs.length,data.labs.length))}</div><div><span>Projects delivered ${icon('box')}</span><strong>${data.projects.filter(p=>projectDone(p)).length}<small> / 6</small></strong><small>Ideas turned into working software</small></div><div><span>Days of fieldwork ${icon('sun')}</span><strong>${state.days.length}<small> active days</small></strong><small>Progress, one session at a time</small></div></div><div class="section-heading"><h2>Your learning path</h2>${link('path','View all lessons '+icon('arrow'),'text-link')}</div><div class="dashboard-stages">${data.stages.map(s=>{const lessons=data.lessons.filter(l=>l.stage===s.id),n=lessons.filter(l=>done(l.id)).length;return link('path/'+s.id,`<span class="stage-index">0${s.id}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.chapters)}</p></div><div class="stage-completion">${n}/6 ${progressBar(pct(n,6))}</div>${icon('arrow')}`,'path-row');}).join('')}</div><div class="dashboard-bottom"><div class="daily-card"><span class="eyebrow">TODAY’S PRACTICE</span><h3>Thinking is good.<br>Trying is better.</h3><p>Choose a small challenge and give it your full attention.</p>${link('lab/'+(data.labs.find(l=>!state.labs.includes(l.id))||data.labs[0]).id,'Open a practice lab '+icon('arrow'),'text-link')}</div><div class="reading-card"><span class="eyebrow">A NOTE FROM THE FIELD</span><h3>${esc(data.articles[0]?.title)}</h3><p>${esc(data.articles[0]?.subtitle)}</p>${link('article/'+data.articles[0]?.id,'Read the field note '+icon('arrow'),'text-link')}</div></div>`);
}
function stageFilters(active=filterStage){return `<div class="filter-tabs" role="group" aria-label="Filter by stage"><button data-stage="0" class="${!active?'selected':''}">All stages</button>${data.stages.map(s=>`<button data-stage="${s.id}" class="${active===s.id?'selected':''}">0${s.id} ${esc(s.title)}</button>`).join('')}</div>`;}
function pathPage(stage){
 const selected=Number(stage)||filterStage;
 return shell(`<div class="page-intro"><div><span class="eyebrow">THE CURRICULUM</span><h1>A path with purpose.</h1><p>36 lessons. Six stages. Build your understanding from the ground up.</p></div><a class="button outline small" href="handbook.md" download>Download study handbook ↓</a></div>${stageFilters(selected)}<div class="curriculum-list">${data.stages.filter(s=>!selected||s.id===selected).map(s=>`<section class="curriculum-stage"><div class="curriculum-heading"><span class="stage-index">0${s.id}</span><div><span class="tiny-label">${esc(s.chapters)}</span><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></div><span class="count-pill">${data.lessons.filter(l=>l.stage===s.id&&done(l.id)).length}/6 completed</span></div><div>${data.lessons.filter(l=>l.stage===s.id).map(l=>link('lesson/'+l.id,`<span class="lesson-check ${done(l.id)?'complete':''}">${done(l.id)?icon('check'):String(l.number).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p></div><span class="lesson-time">${l.minutes} min</span>${icon('arrow')}`,'lesson-row')).join('')}</div></section>`).join('')}</div>`,'path');
}
function codeBlock(code){return `<div class="code-block"><div><span>JAVASCRIPT</span><button data-action="copy-code" aria-label="Copy code">Copy</button></div><pre><code>${esc(code)}</code></pre></div>`;}
function bodySections(body){return body.map(s=>`<section class="prose-section"><h2>${esc(s.heading)}</h2>${(s.paragraphs||[]).map(p=>`<p>${esc(p)}</p>`).join('')}${s.code?codeBlock(s.code):''}</section>`).join('');}
function lessonPage(id){
 const l=data.lessons.find(x=>x.id===id);if(!l)return notFound();
 state.lastLesson=id;save();
 const index=data.lessons.indexOf(l),next=data.lessons[index+1];
 return shell(`<div class="lesson-layout"><article class="lesson-article"><a class="back-link" href="#/path/${l.stage}">← Stage 0${l.stage} · ${esc(stageName(l.stage))}</a><div class="lesson-title"><span class="eyebrow">LESSON ${String(l.number).padStart(2,'0')} / 36</span><h1>${esc(l.title)}</h1><p>${esc(l.subtitle)}</p><div class="inline-meta"><span>${icon('clock')} ${l.minutes} min</span><span>${esc(l.chapter)}</span>${tag(done(id)?'Completed':'Ready when you are',done(id)?'green':'')}</div></div><div class="reading-assignment"><div>${icon('book')}</div><section><span class="tiny-label">READ ALONG IN YOUR BOOK</span><strong>${esc(l.chapter)} · ${esc(l.sections)}</strong><p>Read the assigned sections, then return here to work through the ideas.</p></section><button class="text-button" data-action="book">Open PDF ↗</button></div><section class="objectives"><h2>What you’ll walk away with</h2><ul>${l.objectives.map(o=>`<li>${icon('check')}${esc(o)}</li>`).join('')}</ul></section>${wikiUI.lessonLinks(l)}${bodySections(l.body)}<aside class="callout"><span class="tiny-label">WATCH YOUR STEP</span><ul>${l.pitfalls.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></aside><section class="knowledge-check"><span class="eyebrow">RETRIEVE BEFORE YOU REREAD</span><h2>Check your understanding</h2>${l.quiz.map((q,i)=>{const chosen=state.quiz[id+'-'+i];return `<div class="quiz"><h3><span>0${i+1}</span>${esc(q.question)}</h3><div>${q.options.map((o,j)=>`<button class="quiz-option ${chosen===j?(j===q.answer?'correct':'incorrect'):''}" data-quiz="${i}" data-option="${j}" aria-pressed="${chosen===j}"><span>${String.fromCharCode(65+j)}</span>${esc(o)}${chosen===j?icon(j===q.answer?'check':'close'):''}</button>`).join('')}</div>${chosen!==undefined?`<p class="quiz-feedback ${chosen===q.answer?'correct-text':''}">${chosen===q.answer?'Correct.':'Try again.'} ${esc(q.explanation)}</p>`:''}</div>`;}).join('')}</section><section><span class="eyebrow">PUT IT TO WORK</span><h2>Practice in your own editor</h2><div class="practice-prompts">${l.practice.map((p,i)=>`<details><summary><span>0${i+1}</span>${esc(p.title)}<b>+</b></summary><p>${esc(p.prompt)}</p><h4>You’re done when</h4><ul>${p.success.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`).join('')}</div></section><section class="recap"><h2>Take it with you</h2><ul>${l.recap.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="lesson-note"><label for="lesson-note">Your field notes</label><p>What surprised you? What would you explain differently tomorrow?</p><textarea id="lesson-note" data-note="${id}" placeholder="Write it in your own words…">${esc(state.notes[id]||'')}</textarea><small>Saved automatically on this device.</small></section><div class="lesson-finish"><button class="button ${done(id)?'outline':'orange'}" data-action="complete-lesson" data-id="${id}">${icon('check')} ${done(id)?'Completed · mark incomplete':'Mark lesson complete'}</button>${next?link('lesson/'+next.id,'Next lesson '+icon('arrow'),'text-link'):link('projects','Build your capstone '+icon('arrow'),'text-link')}</div></article><aside class="lesson-rail"><span class="tiny-label">IN THIS LESSON</span>${l.body.map(s=>`<p>${esc(s.heading)}</p>`).join('')}<hr><span class="tiny-label">LEARN BY DOING</span><h3>Give the idea a test drive.</h3><p>Practice this stage’s concepts in an executable lab.</p>${link('lab/'+data.labs.find(x=>x.stage===l.stage)?.id,'Open practice lab '+icon('arrow'),'button dark small')}<hr><small>Original companion material. Keep the book nearby for the full treatment.</small></aside></div>`,'path');
}
function labList(){return shell(`<div class="page-intro"><div><span class="eyebrow">THE PRACTICE LAB</span><h1>Less watching. More doing.</h1><p>48 focused challenges. Real tests. Enough room to figure it out.</p></div><span class="count-pill">${state.labs.length} / ${data.labs.length} solved</span></div>${stageFilters()}<div class="lab-toolbar"><label class="input-search">${icon('search')}<input id="lab-search" placeholder="Search a concept or challenge…" value="${esc(searchText)}"></label><span>Each lab includes hints, tests, and a worked solution.</span></div><div class="lab-grid">${data.labs.filter(l=>(!filterStage||l.stage===filterStage)&&`${l.title} ${l.concept}`.toLowerCase().includes(searchText.toLowerCase())).map(l=>link('lab/'+l.id,`<div class="card-top">${tag(l.difficulty)}<span class="lab-status ${state.labs.includes(l.id)?'solved':''}">${state.labs.includes(l.id)?icon('check'):'↗'}</span></div><span class="tiny-label">STAGE 0${l.stage} · ${esc(l.concept)}</span><h3>${esc(l.title)}</h3><p>${esc(l.prompt).slice(0,135)}${l.prompt.length>135?'…':''}</p><div class="card-meta">${l.minutes} MIN <span>·</span> ${l.tests.length} TESTS ${icon('arrow')}</div>`,'lab-card')).join('')||'<div class="empty-state">No matching labs. Try a broader search.</div>'}</div>`,'labs');}
function labPage(id){
 const l=data.labs.find(x=>x.id===id);if(!l)return notFound();
 return shell(`<a class="back-link" href="#/labs">← All practice labs</a><div class="lab-heading"><div><span class="eyebrow">STAGE 0${l.stage} · ${esc(l.concept)}</span><h1>${esc(l.title)}</h1></div><div id="lab-state">${tag(l.difficulty)} ${tag(state.labs.includes(id)?'Solved':'In progress',state.labs.includes(id)?'green':'')}</div></div><div class="lab-workspace"><section class="lab-brief"><div class="tab-label">THE CHALLENGE</div><div class="lab-brief-content"><p>${esc(l.prompt)}</p><h3>Examples</h3>${l.examples.map(e=>`<div class="example"><small>INPUT</small><pre>${esc(e.input)}</pre><small>OUTPUT</small><pre>${esc(e.output)}</pre></div>`).join('')}<h3>Success criteria</h3><ul class="test-names">${l.tests.map(t=>`<li>${icon('check')}${esc(t.name)}</li>`).join('')}</ul><div class="hint-area"><button class="button outline small" data-action="hint">Reveal a hint <span>${hints}/${l.hints.length}</span></button><div id="hints">${l.hints.slice(0,hints).map((h,i)=>`<p><b>Hint ${i+1}.</b> ${esc(h)}</p>`).join('')}</div></div><details class="solution-details"><summary>View solution & explanation</summary><p>Compare the approach after your own attempt. Reading a solution does not mark this lab as solved.</p>${codeBlock(l.solution)}<button class="text-button" data-action="load-solution">Load solution into editor</button></details></div></section><section class="editor-panel"><div class="editor-header"><span><i></i> ${esc(l.id)}.js</span><div><span id="save-status">Saved locally</span><button data-action="reset-code">Reset</button></div></div><label class="sr-only" for="code-editor">JavaScript solution</label><div class="editor-shell"><div id="line-numbers" aria-hidden="true"></div><textarea id="code-editor" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" aria-describedby="editor-help">${esc(state.code[id]??l.starter)}</textarea></div><div class="editor-toolbar"><span id="editor-help">JavaScript · Ctrl/⌘ + Enter to run</span><button class="button orange small" data-action="run">${icon('play')} Run tests</button></div><div class="test-output" aria-live="polite"><div class="output-header"><span>TEST RESULTS</span><span id="test-summary">READY TO RUN</span></div><div id="test-results"><div class="test-empty">${icon('code')}<p>Your next “aha” is one run away.</p><small>Tests run locally in a fresh worker. 3-second time limit.</small></div></div></div></section></div><p class="lab-footnote">This is a learning sandbox, not a secure grading system. Browser APIs and Node filesystem APIs are practiced in the project briefs and your own editor.</p>`,'labs');
}
function projectDone(p){return p.milestones.every((m,i)=>m.tasks.every((_,j)=>state.projects[`${p.id}-${i}-${j}`]));}
function projectsPage(){return shell(`<div class="page-intro"><div><span class="eyebrow">BUILD YOUR EVIDENCE</span><h1>Knowledge, with something to show.</h1><p>Six projects that turn chapters into decisions, tradeoffs, and working software.</p></div><a class="button outline small" href="project-starters.zip" download>Download all starter kits ↓</a></div><div class="project-grid">${data.projects.map((p,i)=>link('project/'+p.id,`<div class="project-art project-art-${i+1}"><span>PROJECT / 0${i+1}</span><strong>${['$ _','{ data }','◈','await_','&lt;web&gt;','ship()'][i]}</strong><span>${projectDone(p)?'✓ DELIVERED':esc(p.level)}</span></div><div class="project-card-body"><div class="tiny-label">STAGE 0${p.stage} · ~${p.estimatedHours} HOURS</div><h2>${esc(p.title)}</h2><p>${esc(p.subtitle)}</p><span class="text-link">View project brief ${icon('arrow')}</span></div>`,'project-card')).join('')}</div>`,'projects');}
function projectPage(id){const p=data.projects.find(x=>x.id===id);if(!p)return notFound();const total=p.milestones.reduce((n,m)=>n+m.tasks.length,0),completed=p.milestones.reduce((n,m,i)=>n+m.tasks.filter((_,j)=>state.projects[`${id}-${i}-${j}`]).length,0);return shell(`<div class="article-container"><a class="back-link" href="#/projects">← All build projects</a><span class="eyebrow">STAGE 0${p.stage} · ${esc(p.level)} · ~${p.estimatedHours} HOURS</span><h1>${esc(p.title)}</h1><p class="lead">${esc(p.subtitle)}</p><div class="project-progress"><span>${completed} / ${total} acceptance criteria complete</span>${progressBar(pct(completed,total))}</div><section class="prose-section"><h2>The brief</h2><p>${esc(p.brief)}</p><h3>What you’ll ship</h3><ul>${p.deliverables.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></section><h2>Your build plan</h2><div class="milestones">${p.milestones.map((m,i)=>`<section><span class="tiny-label">MILESTONE 0${i+1}</span><h3>${esc(m.title)}</h3>${m.tasks.map((t,j)=>`<label><input type="checkbox" data-project-task="${id}-${i}-${j}" ${state.projects[`${id}-${i}-${j}`]?'checked':''}><span>${esc(t)}</span></label>`).join('')}</section>`).join('')}</div><section class="prose-section"><h2>Review it like a professional</h2><p>Use this rubric for a self-review or ask a peer to review your repository. A checklist records your assessment; it does not automatically verify the software.</p><div class="rubric">${p.rubric.map(r=>`<div><span>${esc(r.criterion)}</span><strong>${r.points} pts</strong></div>`).join('')}</div><h2>Go a little further</h2><ul>${p.stretch.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section class="lesson-note"><label for="project-notes">Build log & repository link</label><textarea id="project-notes" data-note="${id}" placeholder="Repository URL, decisions, bugs, and what you learned…">${esc(state.notes[id]||'')}</textarea><small>Saved automatically on this device.</small></section></div>`,'projects');}
function libraryPage(){return shell(`<div class="page-intro"><div><span class="eyebrow">THE REFERENCE SHELF</span><h1>Good inputs. Better instincts.</h1><p>Original field notes and a curated route through the wider JavaScript world.</p></div><button class="button outline small" data-action="book">${icon('book')} Open your book</button></div><section class="wiki-library-banner"><div><span class="tiny-label">JAVASCRIPT WIKI · ${data.wiki.length} TOPICS</span><h2>The useful answer, within reach.</h2><p>Concise rules, practical examples, and pitfalls linked to your lessons.</p></div>${link("wiki","Open the wiki ↗","button dark small")}</section><div class="section-heading"><h2>Field notes</h2><span class="muted">Original articles for the work between chapters</span></div><div class="article-grid">${data.articles.map((a,i)=>link('article/'+a.id,`<div class="article-number">${String(i+1).padStart(2,'0')}<span>↗</span></div><span class="tiny-label">${a.minutes} MIN READ · ${esc(a.tags[0])}</span><h3>${esc(a.title)}</h3><p>${esc(a.subtitle)}</p>`,'article-card')).join('')}</div><div class="section-heading resource-heading"><h2>A carefully stocked bookshelf</h2><span class="muted">External resources · access may change</span></div><div class="filter-tabs resource-filters">${['All','Documentation','Book','Course','Video','Practice'].map(t=>`<button data-type="${t}" class="${filterType===t?'selected':''}">${t}</button>`).join('')}</div><div class="resource-list">${data.resources.filter(r=>filterType==='All'||r.type===filterType).map(r=>`<a class="resource-row" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><div class="resource-type">${icon(r.type==='Video'?'play':r.type==='Practice'?'code':'book')}</div><div><span class="tiny-label">${esc(r.type)} · ${esc(r.author)}</span><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p></div><div class="resource-meta">${tag(r.access)}<small>Stage ${r.stage} · ${esc(r.level)}</small></div><span>↗</span></a>`).join('')}</div><div class="library-disclaimer"><a class="button outline small" href="field-guide.html" download>Download the complete study guide ↓</a><br><br>The book remains yours. Open a local PDF to read alongside the lessons; it is never uploaded or included in this site. External resources belong to their respective authors.</div>`,'library');}
function articlePage(id){const a=data.articles.find(x=>x.id===id);if(!a)return notFound();return shell(`<article class="article-container"><a class="back-link" href="#/library">← The reference shelf</a><span class="eyebrow">FIELD NOTE · ${a.minutes} MIN READ</span><h1>${esc(a.title)}</h1><p class="lead">${esc(a.subtitle)}</p><div class="article-tags">${a.tags.map(t=>tag(t)).join('')}</div>${bodySections(a.body)}<div class="article-end"><span>KNOWLEDGE IS A START. PRACTICE MAKES IT STICK.</span>${link('labs','Put it to work '+icon('arrow'),'button orange small')}</div></article>`,'library');}
function notebookPage(){const notes=Object.entries(state.notes).filter(([k,v])=>v.trim()&&k!=='general');return shell(`<div class="page-intro"><div><span class="eyebrow">YOUR FIELD NOTES</span><h1>Make a record of the figuring out.</h1><p>Your observations, questions, and small breakthroughs belong here.</p></div></div><div class="notebook-layout"><div><section class="notebook-main"><label for="general-note">The working notebook</label><p>Keep a question log. Explain a concept. Write down what you’ll try next.</p><textarea id="general-note" data-note="general" placeholder="Today I learned…\n\nI’m still wondering…\n\nMy next experiment…">${esc(state.notes.general||'')}</textarea><small>Saved automatically in this browser.</small></section><div class="section-heading"><h2>Notes from your journey</h2><span>${notes.length} entries</span></div>${notes.map(([id,text])=>{const item=data.lessons.find(l=>l.id===id)||data.projects.find(p=>p.id===id);return `<a class="note-entry" href="#/${id.startsWith('lesson')?'lesson':'project'}/${esc(id)}"><h3>${esc(item?.title||id)} ${icon('arrow')}</h3><p>${esc(text.slice(0,250))}</p></a>`;}).join('')||'<div class="empty-state">Your lesson reflections and project logs will appear here.</div>'}</div><aside><div class="backup-card"><span class="eyebrow">KEEP YOUR WORK</span><h3>Your data. Your copy.</h3><p>Progress, lab code, quiz answers, and notes are saved in this browser. Export a backup before changing browsers or clearing site data.</p><button class="button dark" data-action="export">Export backup ↓</button><button class="button outline" data-action="import">Import backup ↑</button><input type="file" id="backup-file" accept="application/json" hidden><small>Import merges your completed lessons and labs; imported notes, code, and answers replace matching entries.</small></div><div class="handbook-card"><span class="eyebrow">YOUR STUDY SYSTEM</span><h3>A plan you can stick to.</h3><p>Session rituals, 8-week and 16-week schedules, review checklists, and a way to measure actual understanding.</p><a class="text-link" href="handbook.md" download>Download handbook ↓</a></div><div class="privacy-card"><h3>A quiet, personal workspace.</h3><p>No account system. No analytics. No subscriptions inside the app. External resources open in a new tab. Offline access becomes available after the first successful load on a supported browser.</p></div></aside></div>`,'notebook');}
function notFound(){return shell(`<div class="empty-state"><h1>That page wandered off.</h1><p>Head back to your learning path.</p>${link('path','Open learning path','button orange')}</div>`);}
function render(){
 if(!data)return;
 wikiUI?.dispose();
 if(worker){worker.terminate();worker=null;clearTimeout(timer);}
 const hash=location.hash;
 if(hash==='#curriculum'||hash==='#method'){if(!$('.landing'))$('#app').innerHTML=home();requestAnimationFrame(()=>$(hash)?.scrollIntoView({behavior:'smooth'}));return;}
 route=hash.replace(/^#\/?/,'').split('/');
 const [page,id]=route;
 const views={'':home,dashboard,path:()=>pathPage(id),lesson:()=>lessonPage(id),labs:labList,lab:()=>labPage(id),projects:projectsPage,project:()=>projectPage(id),wiki:()=>wikiUI.page(id),library:libraryPage,article:()=>articlePage(id),notebook:notebookPage};
 $('#app').innerHTML=(Object.hasOwn(views,page)?views[page]:notFound)();
 document.title=`${page?({dashboard:'Overview',path:'Learning path',labs:'Practice lab',projects:'Build projects',wiki:'JavaScript wiki',library:'Library',notebook:'My notebook'}[page]||'The studio')+' · ':''}JavaScript Fieldwork`;
 if(page==='wiki'&&id){const topic=data.wiki.find(a=>a.id===id);if(topic)document.title=`${topic.title} · JavaScript wiki`;}
 bind();window.scrollTo({top:0,behavior:'instant'});
}
function updateLines(){const e=$('#code-editor');if(e)$('#line-numbers').textContent=e.value.split('\n').map((_,i)=>i+1).join('\n');}
function bind(){
 wikiUI.bind();
 document.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.note]=el.value;activity();}));
 document.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>{filterStage=Number(el.dataset.stage);if(route[0]==='path')location.hash='#/path/'+(filterStage||'');else render();});
 document.querySelectorAll('[data-type]').forEach(el=>el.onclick=()=>{filterType=el.dataset.type;render();document.querySelector('.resource-heading').scrollIntoView();});
 document.querySelectorAll('[data-quiz]').forEach(el=>el.onclick=()=>{const y=scrollY;state.quiz[route[1]+'-'+el.dataset.quiz]=Number(el.dataset.option);activity();render();window.scrollTo(0,y);});
 document.querySelectorAll('[data-project-task]').forEach(el=>el.onchange=()=>{const y=scrollY;state.projects[el.dataset.projectTask]=el.checked;activity();render();window.scrollTo(0,y);});
 $('#lab-search')?.addEventListener('input',e=>{searchText=e.target.value;const cursor=e.target.selectionStart;render();$('#lab-search').focus();$('#lab-search').setSelectionRange(cursor,cursor);});
 const editor=$('#code-editor');
 if(editor){updateLines();editor.addEventListener('input',()=>{state.code[route[1]]=editor.value;const saved=save();updateLines();$('#save-status').textContent=saved?'Saved locally':'Not saved — export backup';});editor.addEventListener('scroll',()=>{$('#line-numbers').scrollTop=editor.scrollTop;});editor.addEventListener('keydown',e=>{if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();editor.setRangeText('  ',editor.selectionStart,editor.selectionEnd,'end');editor.dispatchEvent(new Event('input'));}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();runLab();}});}
 $('#backup-file')?.addEventListener('change',importBackup);
}
async function runLab(){
 if(worker)worker.terminate();clearTimeout(timer);
 const l=data.labs.find(x=>x.id===route[1]),code=$('#code-editor').value;
 state.code[l.id]=code;activity();
 $('#test-summary').textContent='RUNNING…';$('#test-results').innerHTML='<p class="running-message">Running your assertions…</p>';
 const runButton=$('[data-action="run"]');runButton.disabled=true;
 worker=new Worker('runner.js');
 const finish=()=>{worker?.terminate();worker=null;clearTimeout(timer);runButton.disabled=false;};
 timer=setTimeout(()=>{finish();$('#test-summary').textContent='TIME LIMIT';$('#test-results').innerHTML='<p class="error-output">Execution stopped after 3 seconds. Check for an infinite loop or an unresolved promise.</p>';},3000);
 worker.onerror=e=>{finish();$('#test-summary').textContent='ERROR';$('#test-results').innerHTML=`<p class="error-output">${esc(e.message)}</p>`;};
 worker.onmessage=({data:r})=>{finish();const passed=r.results.filter(x=>x.passed).length;$('#test-summary').textContent=`${passed} / ${l.tests.length} PASSED`;$('#test-results').innerHTML=`${r.error?`<p class="error-output">${esc(r.error)}</p>`:''}${r.results.map(t=>`<div class="test-result ${t.passed?'pass':'fail'}">${icon(t.passed?'check':'close')}<div>${esc(t.name)}${t.error?`<small>${esc(t.error)}</small>`:''}</div></div>`).join('')}${r.logs.length?`<div class="console-output"><span>CONSOLE</span><pre>${esc(r.logs.join('\n'))}</pre></div>`:''}`;if(passed===l.tests.length&&!r.error&&!state.labs.includes(l.id)){state.labs.push(l.id);save();$('#lab-state').innerHTML=tag(l.difficulty)+' '+tag('Solved','green');toast('All tests passed. Another idea made real.');}};
 worker.postMessage({code,tests:l.tests});
}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importBackup(e){try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('Backup is too large (5 MB maximum).');const b=JSON.parse(await file.text());if(b.version!==1||!Array.isArray(b.lessons)||!Array.isArray(b.labs))throw Error('Choose a Fieldwork v1 backup.');for(const k of ['projects','notes','code','quiz']){if(!b[k]||typeof b[k]!=='object'||Array.isArray(b[k]))throw Error('Invalid backup structure.');}if(!Object.values(b.notes).every(v=>typeof v==='string')||!Object.values(b.code).every(v=>typeof v==='string')||!Object.values(b.projects).every(v=>typeof v==='boolean')||!Object.values(b.quiz).every(v=>Number.isInteger(v)&&v>=0&&v<=3))throw Error('Invalid backup entries.');const allowedLesson=new Set(data.lessons.map(l=>l.id)),allowedLabs=new Set(data.labs.map(l=>l.id));state.lessons=[...new Set([...state.lessons,...b.lessons.filter(id=>allowedLesson.has(id))])];state.labs=[...new Set([...state.labs,...b.labs.filter(id=>allowedLabs.has(id))])];const allowedKeys={notes:new Set(['general',...allowedLesson,...data.projects.map(p=>p.id)]),code:allowedLabs,quiz:new Set(data.lessons.flatMap(l=>l.quiz.map((_,i)=>l.id+'-'+i))),projects:new Set(data.projects.flatMap(p=>p.milestones.flatMap((m,i)=>m.tasks.map((_,j)=>`${p.id}-${i}-${j}`))))};for(const k of ['projects','notes','code','quiz'])state[k]={...state[k],...Object.fromEntries(Object.entries(b[k]).filter(([key])=>allowedKeys[k].has(key)))};state.days=[...new Set([...state.days,...(Array.isArray(b.days)?b.days.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)):[])])];save();render();toast('Backup imported. Welcome back to your work.');}catch(error){toast(error.message);}}
function modal(html,cls=''){const d=document.createElement('dialog');d.className='modal '+cls;d.innerHTML=`<button class="modal-close icon-button" data-action="close-modal" aria-label="Close">${icon('close')}</button>${html}`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d){d.close();d.remove();}});d.addEventListener('close',()=>d.remove());d.showModal();return d;}
function openBook(page=1){page=Number.isInteger(page)&&page>0?page:1;const d=modal(`<div class="book-modal-header"><span class="eyebrow">YOUR PERSONAL READING ROOM</span><h2>Keep the book close.</h2><p>Select your own PDF. It stays on your device and is never uploaded.${page>1?` Open at PDF page ${page}.`:""}</p><button class="button orange small" data-action="choose-pdf">${icon('book')} Choose your PDF</button><input id="pdf-file" type="file" accept="application/pdf" hidden></div><div id="pdf-reader">${pdfURL?`<iframe title="Your personal PDF" src="${pdfURL}#page=${page}"></iframe>`:'<div class="pdf-empty">Read the assigned book section, then return to the lesson to put it to work.<br><small>You’ll need to reselect your file after reloading this page.</small></div>'}</div>`,'book-modal');d.querySelector('#pdf-file').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))return toast('Please select a PDF.');if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(file);d.querySelector('#pdf-reader').innerHTML=`<iframe title="Your personal PDF" src="${pdfURL}#page=${page}"></iframe>`;};}
function openSearch(){const d=modal(`<span class="eyebrow">FIND YOUR NEXT IDEA</span><label class="input-search">${icon('search')}<input id="global-search" placeholder="Search wiki, lessons, labs, articles, projects…" aria-label="Search the studio" autofocus></label><div id="search-results"><p class="muted">Try “closures”, “async”, or “testing”.</p></div>`,'search-modal');const entries=[...wikiUI.searchEntries(),...data.lessons.map(x=>({...x,type:'lesson',label:'Lesson'})),...data.labs.map(x=>({...x,type:'lab',label:'Lab'})),...data.articles.map(x=>({...x,type:'article',label:'Article'})),...data.projects.map(x=>({...x,type:'project',label:'Project'}))];d.querySelector('input').oninput=e=>{const q=e.target.value.toLowerCase().trim();const matches=q?entries.filter(x=>x.type==='wiki'?matchesQuery(x,q):`${x.title} ${x.subtitle||''} ${x.concept||''}`.toLowerCase().includes(q)).slice(0,16):[];d.querySelector('#search-results').innerHTML=matches.map(x=>`<a href="#/${x.type}/${x.id}"><span>${esc(x.label)}</span><strong>${esc(x.title)}</strong>${icon('arrow')}</a>`).join('')||'<p class="muted">No matches yet. Try another concept.</p>';d.querySelectorAll('#search-results a').forEach(a=>a.onclick=()=>d.close());};}
document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();const main=$('#main');main.setAttribute('tabindex','-1');main.focus();return;}const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
 if(action==='retry-load')location.reload();
 if(action==='menu')$('.sidebar').classList.toggle('mobile-open');
 if(action==='search')openSearch();if(action==='book')openBook(Number(target.dataset.page)||1);if(action==='choose-pdf')$('#pdf-file').click();
 if(action==='close-modal')target.closest('dialog').close();
 if(action==='copy-code'){try{await navigator.clipboard.writeText(target.closest('.code-block').querySelector('code').textContent);target.textContent='Copied';}catch{toast('Select the code to copy it manually.');}}
 if(action==='complete-lesson'){const id=target.dataset.id;if(done(id))state.lessons=state.lessons.filter(x=>x!==id);else state.lessons.push(id);activity();const y=scrollY;render();window.scrollTo(0,y);toast(done(id)?'Lesson complete. Keep building.':'Lesson marked for another visit.');}
 if(action==='run')runLab();
 if(action==='hint'){const l=data.labs.find(x=>x.id===route[1]);hints=Math.min(hints+1,l.hints.length);$('#hints').innerHTML=l.hints.slice(0,hints).map((h,i)=>`<p><b>Hint ${i+1}.</b> ${esc(h)}</p>`).join('');target.innerHTML=`Reveal a hint <span>${hints}/${l.hints.length}</span>`;target.disabled=hints===l.hints.length;}
 if(action==='reset-code'||action==='load-solution'){const l=data.labs.find(x=>x.id===route[1]);if(action==='reset-code'&&!confirm('Replace your current code with the starter?'))return;$('#code-editor').value=action==='reset-code'?l.starter:l.solution;$('#code-editor').dispatchEvent(new Event('input'));toast(action==='reset-code'?'Starter code restored.':'Solution loaded. Run it, then explain why it works.');}
 if(action==='export')download(`fieldwork-backup-${today()}.json`,JSON.stringify(state,null,2));
 if(action==='import')$('#backup-file').click();
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!document.querySelector('dialog[open]'))openSearch();}});
window.addEventListener('hashchange',()=>{hints=0;render();});
// Update the cache even when an old cached response prevents content from loading.
if('serviceWorker' in navigator)navigator.serviceWorker.register(new URL('./sw.js',import.meta.url)).then(registration=>registration.update()).catch(()=>{});
try{const [curriculum,labs,library,wiki]=await Promise.all(['curriculum','labs','library','wiki'].map(name=>loadContent(name)));data={...curriculum,...labs,...library,...wiki};wikiUI=createWiki({data,shell,esc,link,codeBlock});render();}catch(error){const auth=error.kind==='auth';$('#app').innerHTML=`<main id="main" class="boot"><h1>${auth?'Sign in to your studio.':'The studio couldn’t open.'}</h1><p>${esc(error.message||'Check your connection and try again.')}</p>${auth?'<p><a class="button orange" href="/signin-with-chatgpt?return_to=%2F">Continue with ChatGPT</a></p>':''}<button class="button outline" data-action="retry-load">Reload studio</button></main>`;}

